1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.function.Consumer;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * Domain tables in FK-dependency order (child before parent). Referential integrity is dropped
34	     * around the truncates so the order is not load-bearing, but keeping it sensible documents the
35	     * shape. A new table joins the reset by being added to this list — no new statement to write.
36	     */
37	    private static final List<String> DOMAIN_TABLES =
38	            List.of("line_item", "invoice", "task", "contact", "project", "client");
39	
40	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
41	    @PostMapping("/reset")
42	    public void reset() {
43	        audit.clear();
44	        // Drop referential integrity around the truncates: RESTART IDENTITY on each, then restore
45	        // it. That makes the order above cosmetic and clears every FK-referenced table cleanly.
46	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
47	        for (String table : DOMAIN_TABLES) {
48	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
49	        }
50	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
51	    }
52	
53	    /**
54	     * Insert the fixture a spec needs; the payload shape evolves with the schema. Each table is one
55	     * {@link #seedRows} call: name the fixture key, then map a row to an INSERT. A new table is one
56	     * more call here — the null-check and per-row loop are shared, not repeated.
57	     */
58	    @PostMapping("/seed")
59	    public void seed(@RequestBody Map<String, Object> fixture) {
60	        seedRows(fixture, "clients", c -> jdbc.update(
61	                "INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
62	                asLong(c, "id"), c.get("name"), c.get("email")));
63	
64	        seedRows(fixture, "projects", p -> jdbc.update(
65	                "INSERT INTO project (id, name, client_id) VALUES (?, ?, ?)",
66	                asLong(p, "id"), p.get("name"), asLong(p, "clientId")));
67	
68	        seedRows(fixture, "tasks", t -> jdbc.update(
69	                "INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
70	                asLong(t, "id"), asLong(t, "projectId"), t.get("title"),
71	                Boolean.TRUE.equals(t.get("done"))));
72	
73	        seedRows(fixture, "contacts", c -> jdbc.update(
74	                "INSERT INTO contact (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
75	                asLong(c, "id"), asLong(c, "clientId"),
76	                c.get("name"), c.get("email"), c.get("role")));
77	
78	        // An invoice is now itemised: its amount is the sum of qty * unit price across its lines
79	        // (nested under the invoice in the fixture). The stored amount is the derived total — the
80	        // fixture may still supply an explicit "amount" for an invoice with no lines, otherwise it
81	        // is computed here so the invoice list reads the same total the lines add up to.
82	        seedRows(fixture, "invoices", i -> {
83	            List<Map<String, Object>> lines = asRows(i.get("lineItems"));
84	            double computed = 0;
85	            for (Map<String, Object> li : lines) {
86	                computed += ((Number) li.get("qty")).doubleValue()
87	                        * ((Number) li.get("unitPrice")).doubleValue();
88	            }
89	            Object explicit = i.get("amount");
90	            double amount = explicit == null ? computed : ((Number) explicit).doubleValue();
91	            jdbc.update(
92	                    "INSERT INTO invoice (id, project_id, amount, status, issued_date, due_date) "
93	                            + "VALUES (?, ?, ?, ?, ?, ?)",
94	                    asLong(i, "id"), asLong(i, "projectId"), amount,
95	                    i.get("status") == null ? "UNPAID" : i.get("status"),
96	                    i.get("issuedDate"), i.get("dueDate"));
97	            for (Map<String, Object> li : lines) {
98	                jdbc.update(
99	                        "INSERT INTO line_item (id, invoice_id, description, qty, unit_price) "
100	                                + "VALUES (?, ?, ?, ?, ?)",
101	                        asLong(li, "id"), asLong(i, "id"), li.get("description"),
102	                        ((Number) li.get("qty")).intValue(),
103	                        ((Number) li.get("unitPrice")).doubleValue());
104	            }
105	        });
106	    }
107	
108	    /** A nested optional list of rows (e.g. an invoice's line items), or empty when the key is absent. */
109	    @SuppressWarnings("unchecked")
110	    private static List<Map<String, Object>> asRows(Object value) {
111	        return value == null ? List.of() : (List<Map<String, Object>>) value;
112	    }
113	
